.mdc-checkbox {
  // Add the slots for MDC checkbox.
  @include mdc-checkbox-theme.theme-styles(map.merge($mdc-checkbox-slots, (
    // Angular Material focuses the native input. rather than the element MDC expects,
    // so we create this slot ourselves.
      selected-focus-icon-color: null,
      unselected-focus-icon-color: null,
    // MDC expects `.mdc-checkbox__ripple::before` to be the state layer, but we use
    // `.mdc-checkbox__ripple` instead, so we emit the state layer slots ourselves.
      unselected-hover-state-layer-opacity: null,
      unselected-hover-state-layer-color: null,
      unselected-focus-state-layer-opacity: null,
      unselected-focus-state-layer-color: null,
      unselected-pressed-state-layer-opacity: null,
      unselected-pressed-state-layer-color: null,
      selected-hover-state-layer-opacity: null,
      selected-hover-state-layer-color: null,
      selected-focus-state-layer-opacity: null,
      selected-focus-state-layer-color: null,
      selected-pressed-state-layer-opacity: null,
      selected-pressed-state-layer-color: null,
  )));

  @include token-utils.use-tokens(tokens-mdc-checkbox.$prefix, $mdc-checkbox-slots) {
    // MDC expects focus on .mdc-checkbox, but we focus the native element instead, so we need to
    // emit a our own slot for the focus styles.
    .mdc-checkbox__native-control:enabled:focus {
      // Extra `:focus` included to achieve higher specificity than MDC's `:hover` style.
      &:focus:not(:checked):not(:indeterminate) ~ .mdc-checkbox__background {
        @include token-utils.create-token-slot(border-color, unselected-focus-icon-color);
      }

      &:checked,
      &:indeterminate {
        & ~ .mdc-checkbox__background {
          @include token-utils.create-token-slot(border-color, selected-focus-icon-color);
          @include token-utils.create-token-slot(background-color, selected-focus-icon-color);
        }

@include _icon-color(
  map.get($theme, unselected-icon-color),
  map.get($theme, selected-icon-color)
);

&:hover {
  @include _icon-color(
    map.get($theme, unselected-hover-icon-color),
    map.get($theme, selected-hover-icon-color)
  );
}

@include ripple-theme.focus() {
  @include _icon-color(
    map.get($theme, unselected-focus-icon-color),
    map.get($theme, selected-focus-icon-color)
  );
}

@include ripple-theme.active() {
  @include _icon-color(
    map.get($theme, unselected-pressed-icon-color),
    map.get($theme, selected-pressed-icon-color)
  );

///
/// Helps select the checkbox background only when its native control is in
/// unmarked & enabled state.
/// @access private
///
@mixin if-unmarked-enabled_ {
  .mdc-checkbox__native-control:enabled:not(:checked):not(:indeterminate):not([data-indeterminate='true'])
    ~ {
    @content;
  }

// State selector variables used for state selector mixins below.
$_hover-selector: '&:hover';
$_focus-selector: '&.mdc-ripple-upgraded--background-focused, &:not(.mdc-ripple-upgraded):focus';
$_active-selector: '&:not(:disabled):active';

@function get-color-tokens($config) {
  $foreground: map.get($config, foreground);
  $accent: map.get($config, accent);
  $is-dark: map.get($config, is-dark);
  $foreground-base: theming.get-color-from-palette($foreground, base);
  $accent-default: theming.get-color-from-palette($accent, default);
  $disabled-color: theming.get-color-from-palette($foreground, base, 0.38);
  $selected-color: theming.get-color-from-palette($accent);
  $border-color: theming.get-color-from-palette($foreground, base, 0.54);
  $active-border-color:
    theming.get-color-from-palette(palette.$gray-palette, if($is-dark, 200, 900));

  @return (
    // The color of the checkbox fill when the checkbox is selected and disabled.
    disabled-selected-icon-color: $disabled-color,
    // The color of the checkbox border when the checkbox is unselected and disabled.
    disabled-unselected-icon-color: $disabled-color,
    // The color of the checkmark when the checkbox is selected.
    selected-checkmark-color: _contrast-tone($selected-color, $is-dark),
    // The color of the checkbox fill when the checkbox is selected and focused.
    selected-focus-icon-color: $selected-color,
    // The color of the checkbox fill when the checkbox is selected and hovered.
    selected-hover-icon-color: $selected-color,
    // The color of the checkbox fill when the checkbox is selected.
    selected-icon-color: $selected-color,
    // The color of the checkbox fill when the checkbox is selected an pressed.
    selected-pressed-icon-color: $selected-color,
    // The color of the checkbox border when the checkbox is unselected and focused.
    unselected-focus-icon-color: $active-border-color,
    // The color of the checkbox border when the checkbox is unselected and hovered.
    unselected-hover-icon-color: $active-border-color,
    // The color of the checkbox border when the checkbox is unselected.
    unselected-icon-color: $border-color,
    // The color of the checkbox border when the checkbox is unselected and pressed.
    unselected-pressed-icon-color: $border-color,
    // The color of the ripple when the checkbox is selected and focused.
    selected-focus-state-layer-color: $accent-default,
    // The color of the ripple when the checkbox is selected and hovered.
    selected-hover-state-layer-color: $accent-default,
    // The color of the ripple when the checkbox is selected and pressed.
    selected-pressed-state-layer-color: $accent-default,
    // The color of the ripple when the checkbox is unselected and focused.
    unselected-focus-state-layer-color: $foreground-base,
    // The color of the ripple when the checkbox is unselected and hovered.
    unselected-hover-state-layer-color: $foreground-base,
    // The color of the ripple when the checkbox is unselected and pressed.
    unselected-pressed-state-layer-color: $foreground-base,

/// @deprecated Contains typography declarations now part of theme-styles.
@mixin deprecated-static-styles-without-ripple(
  $query: feature-targeting.all()
) {
  @include _deprecated-typography-styles($query: $query);
  @include _static-styles-base($query: $query);
}

@mixin _deprecated-typography-styles($query) {
  .mdc-button {
    @include typography.typography(button, $query);
  }

@mixin _root-structure($query) {
  $feat-structure: feature-targeting.create-target($query, structure);

  @include elevation-theme.overlay-surface-position($query: $query);
  @include elevation-theme.overlay-dimensions(100%, $query: $query);

  @include feature-targeting.targets($feat-structure) {
    display: inline-flex;
    // position: relative; already set in mdc-elevation-overlay-surface-position
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    min-width: 64px;
    border: none;
    outline: none;
    /* @alternate */
    line-height: inherit;

@function typography-level-config-to-mdc($mat-config, $mat-level) {
  $mdc-level: map.get($mat-typography-mdc-level-mappings, $mat-level);

  $result-with-nulls: map.merge(
      if($mdc-level,
          map.get(mdc-typography.$styles, $mdc-level),
          (
            text-decoration: none,
            -moz-osx-font-smoothing: grayscale,
            -webkit-font-smoothing: antialiased
          )),
      if($mat-level,
          (
            font-size: typography-utils.font-size($mat-config, $mat-level),
            line-height: typography-utils.line-height($mat-config, $mat-level),
            font-weight: typography-utils.font-weight($mat-config, $mat-level),
            letter-spacing: typography-utils.letter-spacing($mat-config, $mat-level),
            font-family: typography-utils.font-family($mat-config, $mat-level),
            // Angular Material doesn't use text-transform, so disable it.
            text-transform: none,
          ),

  @include datepicker-legacy-compat.legacy-button-compat-theme((
      color: $config,
      typography: null,
      density: null,
  ));
}

/// @deprecated Use `mat.button-typography` instead. See https://material.angular.io/guide/mdc-migration for information about migrating.
/// @breaking-change 17.0.0
@mixin typography($config-or-theme) {
  $config: typography.private-typography-to-2014-config(
      theming.get-typography-config($config-or-theme));
  .mat-button, .mat-raised-button, .mat-icon-button, .mat-stroked-button,
  .mat-flat-button, .mat-fab, .mat-mini-fab {
    font: {
      family: typography-utils.font-family($config, button);
      size: typography-utils.font-size($config, button);
      weight: typography-utils.font-weight($config, button);
    }
  }

  @include datepicker-legacy-compat.legacy-button-compat-theme((
      color: null,
      typography: $config,
      density: null,
  ));
}

@mixin _density($config-or-theme) {
  @include datepicker-legacy-compat.legacy-button-compat-theme((
      color: null,
      typography: null,
      density: theming.get-density-config($config-or-theme)
  ));

